catalog_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
    if (isLoading || newValue == '') {
        g_form.setValue('validation_progress', 'step0'); //Pending Upload
        return;
    }

    g_form.setValue('validation_progress', 'step1'); //Please wait while file is being Validated

    if (newValue != '') {
        g_form.setValue('validation_progress', 'step2'); //Upload Successful

    }

    var currentTradeMarket = g_form.getDisplayValue('owning_business'); // Get this from another form field if needed
    g_form.setValue('validation_progress', 'step3'); //Validation in Progress
    var checkIfEmptyFile = new GlideAjax('x_938076_now_utils.MSSCustodyBulkFileUpload');
    checkIfEmptyFile.addParam('sysparm_name', 'checkBulkValidationStatus');
    checkIfEmptyFile.addParam('sysparm_market', currentTradeMarket);
    checkIfEmptyFile.getXMLAnswer(checkifemptyRec);




    function checkifemptyRec(response) {
        g_form.addErrorMessage('answer....' + response);


        var recordDetails = response.split("/");
        var result = recordDetails[0] ? recordDetails[0] : 'NA';
        var totalRecordCount = recordDetails[1] ? recordDetails[1] : 'NA';
        var summaryErrorRecords = recordDetails[2] ? recordDetails[2] : 'NA';
        var summaryValidRecords = recordDetails[3] ? recordDetails[3] : 'NA';
        var errorrTrades = recordDetails[4] ? recordDetails[4] : 'NA'; //this will hold array of 

        try {
            g_form.setValue('validation_progress', 'step4');
            //  g_form.addErrorMessage('answer....' + result);

            if (result == "Errors Found" || result == "No Errors" || result == "Allow Partially" || result == "Validation Failed") {

                if (result == "No Errors") {

                    g_form.setValue('validation_progress', 'step4'); //Validation Successful
                } else if (result == "Errors Found") {

                    g_form.setValue('validation_progress', 'step5'); //Validation Failed

                } else if (result == "Allow Partially") {

                    g_form.setValue('validation_progress', 'step6'); //Validation Failed

                }


                spModal.open({
                    title: 'Validation Errors',
                    widget: 'bulk_file_upload_error_details', // Your widget's sys_id or widget ID
                    widgetInput: {
                        tradeMarket: currentTradeMarket,
                        validationSummary: response
                    },

                    size: 'lg' // large modal

                }).then(function(result) {
                    // Handle modal close if needed
                    console.log('Modal closed, result:', result);
                });

            } else if (result == "No records Found") {

                g_form.setValue('validation_progress', 'step5'); //Validation Failed

                spModal.open({
                    title: 'Empty File Alert!',
                    widget: 'bulk_error_validation_empty_alert', // Your widget's sys_id or widget ID
                    widgetInput: {
                        //tradeMarket: currentTradeMarket
                        //attachmentSysId: attachmentSysId,
                    },

                    size: 'lg' // large modal

                }).then(function(result) {
                    // Handle modal close if needed
                    console.log('Modal closed, result:', result);
                });


            }

        } catch (ex) {
            g_form.addErrorMessage('Error from CLient ' + ex);
        }


    }











}
